-- database: admin
SELECT n.nspname AS schema_name, c.relname AS table_name, k.conname AS constraint_name, CASE k.contype WHEN 'p' THEN 'PRIMARY KEY' WHEN 'u' THEN 'UNIQUE' WHEN 'f' THEN 'FOREIGN KEY' END AS constraint_type, pg_get_constraintdef(k.oid) AS definition, fn.nspname AS referenced_schema, f.relname AS referenced_table FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid JOIN pg_namespace n ON n.oid = c.relnamespace LEFT JOIN pg_class f ON f.oid = k.confrelid LEFT JOIN pg_namespace fn ON fn.oid = f.relnamespace WHERE k.contype IN ('p', 'u', 'f') AND n.nspname = :schema ORDER BY n.nspname, c.relname, k.conname;
-- params: {"schema":"Odd\"Schema's"}
